INSERT INTO "public"."projects" ("slug", "title", "category", "shortDescription", "image", "imageAlt", "date", "featured", "purpose", "description", "components", "steps", "notes", "links", "code", "gallery", "created_at") VALUES
	('lab-2a-power-supply', 'Lineární laboratorní zdroj 0-30V / 0-2A', 'Napájení', 'Spolehlivý nastavitelný lineární zdroj s proudovým omezením postavený na osvědčeném zapojení.', '/projects/lab-2a-power-supply.jpg', 'Přední panel laboratorního zdroje s voltmetrem a ampérmetrem', '2026-06-10', true, 'Základní spolehlivý zdroj pro napájení a oživování bastlířských projektů s plynulou regulací napětí a proudu.', 'Lineární regulace zajišťuje čisté výstupní napětí bez spínacího rušení. Pro výkonový tranzistor je použit robustní chladič s tichým ventilátorem.', '[{"qty": "1×", "name": "Transformátor 24V AC 3A"}, {"qty": "1×", "name": "Výkonový tranzistor 2N3055"}, {"qty": "3×", "name": "Operační zesilovače TL081"}, {"qty": "1×", "name": "Panelový měřič napětí a proudu"}]', '[{"body": "Diodový můstek s filtrační kapacitou 4700uF/50V.", "title": "Usměrňovač a filtrace"}, {"body": "Montáž 2N3055 na velký hliníkový chladič s izolační slídovou podložkou.", "title": "Chlazení tranzistoru"}]', NULL, '[]', NULL, '[]', '2026-09-10 21:09:24.883234+00'),
	('scooter-controller-repair', 'Oprava řídící jednotky elektrokoloběžky pok', 'Opravy', 'Diagnostika proražených MOSFETů a oprava motorových fází na řídící jednotce.', '/projects/scooter-controller-repair.jpg', 'Plošný spoj řídící jednotky s výkonovými MOSFETy', '2026-05-05', false, 'Oprava nefunkční řídící jednotky, kde motor při rozjezdu cukal a vyhazoval zkrat.', 'Při diagnostice multimetrem na diodovém testu byla zjištěna proražená dvojice spínacích N-MOSFETů na jedné z fází motoru. Následovala výměna za kvalitnější s nižším Rds(on).', '[{"qty": "6×", "name": "MOSFET tranzistory (např. IRFB4110 / NCEP85T14)"}, {"qty": "1×", "name": "Teplovodivá pasta / podložky"}, {"qty": "1×", "name": "Kvalitní bezolovnatá pájka a tavidlo"}]', '[{"body": "Změř multimetrem v režimu diody odpor mezi GND a každou motorovou fází, a mezi VCC a fázemi.", "title": "Měření fází"}, {"body": "Odpájej vadné tranzistory odsávačkou, očisti pady a osaď novou sadu.", "title": "Výměna proražených kusů"}]', NULL, '[]', NULL, '[]', '2026-09-10 21:09:24.883234+00'),
	('3d-enclosure-esp32', '3D tisk krabičky pro projekt s ESP32', '3D tisk', 'Návrh a tisk odolné krabičky z PETG pro venkovní čidlo s montáží na zeď.', '/projects/3d-enclosure-esp32.jpg', '3D tiskárna tisknoucí plastovou krabičku', '2026-04-12', false, 'Chránit elektroniku před prachem a vlhkostí v odolném pouzdře navrženém přesně na míru desky a displeje.', 'Model byl navržen ve Fusion 360 s tolerancemi 0.2 mm pro snadné zacvaknutí víčka. Vytištěno z materiálu PETG pro vyšší teplotní odolnost.', '[{"qty": "~60g", "name": "PETG filament (černý nebo šedý)"}, {"qty": "4×", "name": "Závitové mosazné vložky M3"}, {"qty": "4×", "name": "Šroubky M3x8mm"}]', '[{"body": "Při návrhu počítej s drobným smrštěním materiálu a přidej vůli na konektory.", "title": "Modelování a tolerance"}, {"body": "Mosazné vložky se zataví do předem vytištěných otvorů hrotem páječky.", "title": "Zatavení vložek"}]', NULL, '[]', NULL, '[]', '2026-09-10 21:09:24.883234+00'),
	('esp32-teplomer', 'ESP32 Teploměr s OLED displejem-pokus123', 'ESP32', 'Wi-Fi teploměr s BME280 senzorem a SSD1306 OLED displejem. Posílá data na server v reálném čase.', '/projects/esp32-teplomer.jpg', 'Breadboard s mikrokontrolérem a senzorem teploty', '2025-08-15', true, 'Měřit teplotu, vlhkost a tlak v dílně a data odesílat přes Wi-Fi na webový dashboard pro sledování historie.', 'Tento projekt vznikl, protože jsem potřeboval sledovat teplotu a vlhkost v dílně, abych věděl, kdy je bezpečné tam nechat citlivé součástky. ESP32 se stará o čtení BME280 a zobrazuje aktuální hodnoty na OLED displeji. Každých 60 sekund pošle data přes MQTT na Home Assistant.', '[{"qty": "1×", "link": "https://www.espressif.com", "name": "ESP32 DevKit V1"}, {"qty": "1×", "name": "BME280 senzor (teplota, vlhkost, tlak)"}, {"qty": "1×", "name": "SSD1306 OLED 0.96\" I2C"}, {"qty": "1×", "name": "Breadboard 830 bodů"}, {"qty": "sada", "name": "Propojovací kablíky"}, {"qty": "1×", "name": "USB-C napájecí kabel"}]', '[{"body": "Připoj VCC na 3.3V, GND na GND, SDA na GPIO 21, SCL na GPIO 22. Senzor komunikuje přes I2C na adrese 0x76.", "title": "Zapojení senzoru BME280"}, {"body": "OLED používá také I2C, takže SDA a SCL sdílí stejné piny jako BME280. Adresa displeje je 0x3C.", "title": "Zapojení OLED displeje"}]', NULL, '[]', NULL, '[]', '2026-09-10 21:09:24.883234+00'),
	('arduino-led-pasma', 'Arduino WS2812B adresovatelný LED pásek', 'Arduino', 'Efektní osvětlení pracovního stolu s adresovatelnými LED diodami WS2812B a Arduinem Nano.', '/projects/arduino-led-pasma.jpg', 'Barevné LED osvětlení na stole', '2026-07-20', false, 'Vyrobit dynamické podsvícení pracovního stolu s možností přepínání profilů tlačítkem.', 'LED pásek WS2812B nabízí individuální řízení každé diody. Arduino Nano se stará o generování světelných efektů pomocí knihovny FastLED.', '[{"qty": "1×", "name": "Arduino Nano V3"}, {"qty": "1×", "name": "WS2812B LED pásek 60 LED/m (2m)"}, {"qty": "1×", "name": "Napájecí zdroj 5V 4A"}, {"qty": "1×", "name": "Kondenzátor 1000uF 6.3V+"}, {"qty": "1×", "name": "Rezistor 470 ohm"}]', '[{"body": "Kondenzátor zapoj paralelně k napájení LED pásku co nejblíže konektoru pro vyhlazení proudových špiček.", "title": "Příprava napájení"}, {"body": "Do série mezi pin D6 Arduina a datový vstup DIN pásku vlož rezistor 470 ohm pro ochranu první diody.", "title": "Datová linka"}]', 'Nikdy nenapájej více než 10 LED přímo z 5V pinu Arduina!', '[]', NULL, '[]', '2026-09-10 21:09:24.883234+00'),
	('laser-engraved-panel', 'Gravírovaný přední panel přístroje', 'DIY', 'Výroba popisků a výřezů pro ovládací prvky z dvouvrstvého plastu pomocí laseru.', '/projects/laser-engraved-panel.jpg', 'Detail laserového gravírování na akrylový panel', '2026-03-01', false, 'Dát bastlířskému přístroji čistý, profesionální a přehledný vzhled.', 'Použití dvouvrstvého gravírovacího plastu (černo-bílý). Laser nejdříve odpaří tenkou černou povrchovou vrstvu pro nápisy a stupnice, a následně vyřízne otvory pro potenciometry a konektory.', '[{"qty": "1ks", "name": "Dvouvrstvý akrylátový plast 1.5mm"}, {"qty": "1×", "name": "Vektorový grafický software (Inkscape / LightBurn)"}]', '[{"body": "Vektory pro řez označ červeně, grafiku pro gravírování černě.", "title": "Příprava grafiky"}, {"body": "Nejprve spusť vrstvu gravírování, až poté finální ořez celého panelu.", "title": "Laserování"}]', NULL, '[]', NULL, '[]', '2026-09-10 21:09:24.883234+00'),
	('menic-pro-ccfl', 'Měnič pro CCFL', 'Napájení', 'Měnič (nebo také invertor) pro CCFL je obvod, který slouží k napájení zářivek CCFL, tedy zářivek se studenou katodou (Cold Cathode Fluorescent Lamp). Tyto obvod', 'data:image/png;base64,', 'Měnič pro CCFL', '2026-09-11', true, '', '<p><strong>Měnič pro CCFL</strong></p><p>     Měnič (nebo také invertor) pro CCFL je obvod, který slouží k napájení zářivek CCFL, tedy zářivek se studenou katodou (Cold Cathode Fluorescent Lamp). Tyto obvody obvykle používají jednoduchý měnič pracující na vysoké frekvenci a miniaturní VN transformátor. Výstupní proud je omezován kapacitně pomocí VN kondenzátoru s malou kapacitou (řádově desítky pF). Zářivka se studenou katodou (CCFL) má pouze 2 vývody, protože nemá žádné žhavení. Používá se nejčastěji k podsvětlení LCD panelů v monitorech a LCD televizorech, k tuningu PC a aut a dekoračním efektům. Možné je i jejich použití k osvětlování. Kromě bílých existují i barevné a UV (černé světlo). Kapacitní omezování proudu je možné díky tomu, že výstupní napětí měniče má sinusový průběh. Měnič pracuje v rezonančním režimu. Jedná se o měnič buzený nikoliv napětím, ale proudem. To zajišťuje tlumivka L1. Proud zářivkami (a tím i výkon) lze měnit změnou C1 a C2. Pracovní frekvence je asi 50kHz. Lze ji ovlivnit hodnotou C3. Změnou frekvence se mění i výkon. Jas zářivek lze regulovat změnou napájecího napětí v rozmezí od 5V do 12V. Regulace je možná v rozmezí cca od 5-10% do 100% jasu. Při menším napětí než 5V se může stát, že bude svítit jen část zářivek (viz video níže). Jeden konec zářivek se začíná rozsvěcet při cca 1,5V a celé CCFL zářivky svítí od 5V. Při zapojování Tr1 a CCFL je nutno dodržet studené a živé konce (studené konce trafa a zářivek mají slabší izolaci než ty živé). Měnič jsem úspěšně otestoval s tranzistory typu 2SC5707, 2SC1384 a BD139. Tr1 je možné získat z LCD monitoru nebo jiného zařízení s CCFL. Navíjení vlastními silami by bylo obtížné vzhledem k velkému počtu závitů velmi tenkým vodičem. Možné je převinutí primárů traf, která měla jen jeden primár (určena pro měniče s MOSFETy a řídícím integrovaným obvodem). Zářivek lze použít i jiný počet - záleží na výkonu trafa. Já jsem měnič testoval na trubicích 2x350mm z 17" monitorů. Identifikoval jsem je jako typ s parametry: Startovací napětí 1200V, provozní napětí 850V, max. proud 5mA, max. výkon 4,25W, doba náběhu 3 minuty, budící frekvence 20 - 100kHz. Účinnost měniče je cca 80-90%, takže příkon trubic lze odhadnout jako 0,85 x příkon měniče, tedy <strong>P<sub>trubic</sub> = 0,85 x U<sub>vstupní</sub> x I<sub>vstupní</sub> </strong>. Při napájení 12V by tedy měnič se dvěma těmito trubicemi měl odebírat 833mA. Pokud výkon neodpovídá, lze ho upravit změnou kapacity C1 a C2 (menší kapacita = menší výkon). Jemně ho lze doladit i změnou frekvence změnou C3.</p><p><strong>     Pozor! Na výstupu měniče je vysoké napětí! Vše děláte na vlastní nebezpečí, za vaše případné újmy neberu zodpovědnost.</strong></p><p><br /></p><p><img src="data:image/png;base64," /><br />Obr. 1 - Schéma měniče (invertoru) pro CCFL (zářivky se studenou katodou).<br /><br /><img src="data:image/jpeg;base64," /><br />Testování měniče pro CCFL s tranzistory 2SC5707 (C5707)<br /><br /><img src="data:image/jpeg;base64," /><br />Tranzistor C5707, tlumivka TL1 a VN transformátorek.<br /><br /><img src="data:image/jpeg;base64," /><br />Průběh napětí na kolektoru jednoho z tranzistorů - "půlsinusovka" na <a href="https://danyk.cz/osc.html">osciloskopu</a>.<br /><br /><img src="data:image/jpeg;base64," /><br />Různé CCFL z 17" monitorů.<br /><br /><img src="data:image/jpeg;base64," /><br />Detail konců s elektrodami.</p>', '[]', '[]', NULL, '[]', NULL, '[]', '2026-09-11 18:49:23.412959+00'),
	('nf-zesilovac-k-pcpc-audio-amplifier', 'Nf zesilovač k PCPC audio amplifier', 'Mikroelektronika', 'Proč zesilovač', 'data:image/jpeg;base64,', 'Nf zesilovač k PC PC audio amplifier', '2026-09-16', true, '', '<p><strong>Nf zesilovač k PC<br />PC audio amplifier</strong></p><p><strong>Proč zesilovač</strong></p><p>Před nedávnem jsem vyměnil v PC zvukovou kartu za novější. Protože používám k PC klasické pasivní reproduktorové soustavy a nová zvuková karta už neměla výkonový zesilovač, nezbylo, než přiměřený zesilovač postavit. Zesilovač měl mít snadno přepínatelný výstup na sluchátka, výstup na subwoofer, malé zkreslení a malý šum. Naopak nemusí mít tónové korekce, které v případě potřeby "umí" zvuková karta nebo jsou realizovány softwarově (WinAmp)</p><p>První verze zesilovače byla osazena obvodem TDA2004 a příliš se neosvědčila. Zmíněný obvod měl velký šum, který mi velmi vadil při poslechu na sluchátka a slyšitelné zkreslení. Když jsem se probíral katalogovými údaji integrovaných obvodů pro nf zesilovače, přišel jsem na zajímavý jev. Naprostá většina IO je optimalizována na určité zesílení. Udávaný šum na výstupu zesilovačů byl přímo úměrný zesílení IO. Jinak řečeno: vstupní obvod běžných nf zesilovačů šumí řádově stejně. Šum na výstupu IO je tím větší, čím má IO větší zesílení. Protože u zesilovače k PC vystačíme se zesílením 3 až 5, je vhodné vybrat IO s co nejmenším zesílením. Tomuto požadavku vyhovuje obvod TDA1517, který má zesílení jen 20 dB, tj. 10x.</p><p><strong>Popis zapojení</strong></p><p>Zapojení nf zesilovače je na obr. 1. Zesilovač je velmi jednoduchý. Zapojení obvodu TDA1517, doporučené výrobcem, je doplněno o napájecí zdroj, regulátor hlasitosti, výstup signálu pro subwoofer a přepínač signálu pro sluchátka. Přepínání signálu do sluchátek zvláštním přepínačem se ukázalo mnohem praktičtější než zasunutím konektoru sluchátek do zdířky. Správně by přepínač měl odpojit i signál výstupu pro subwoofer, ale protože po přepnutí na sluchátka musíme zmenšit hlasitost (sluchátka jsou mnohem citlivější), může zůstat subwoofer připojený. Odpory rezistorů R1 a R2 podle potřeby upravíme tak, aby při maximální hlasitosti zesilovač ještě nezkresloval.</p><p>Zesilovač může být napájen napětím v rozsahu 6 až 18 V. Pro běžný poslech hudby při práci na PC a hraní her vyhoví transformátor s výstupním napětím 9 V a výkonem asi 5 VA. Po usměrnění získáme napětí naprázdno asi 14 V. Použil jsem transformátor z vraku staré kalkulačky s tiskárnou, který dodal napětí 10 V při proudu 0,5 A. Použijete-li transformátor s menším výkonem, doporučuji zvětšit kapacitu kondenzátorů C7 a C8. Zesilovač zapínám současně s PC. Budete-li jej zapínat a vypínat samostatně, použijte "tlumicí" člen R4 C9. Omezí se tak lupanec při vypnutí zesilovače.</p><p>Zesilovač můžete použít také pro walkmany, discmany a jiné "sluchátkové" zdroje signálu. V tom případě nepoužijeme rezistory R1 a R2 a signál přivedeme přímo na regulátor hlasitosti.</p><p><img src="data:image/gif;base64," /></p><p>Obr. 1. Nf zesilovač k PC<br />Fig. 1. PC audio amplifier</p><p><strong>Stavba zesilovače</strong></p><p>Zesilovač je tak jednoduchý, že jsem ho postavil na kousku univerzální desky. Zvýšenou pozornost je v tomto případě nutno věnovat správnému propojení zemí. Vhodné propojení zemí je na obr. 2. Integrovaný obvod připevníme buď na kraj chladiče, nebo musíme použít podložku z kousku tlustšího hliníkového plechu. Já jsem zesilovač postavil do papírové krabice (měla to být prozatímní verze), jako chladič slouží hliníkový plech na zadní straně. Pro přívod signálu doporučuji použít asi polovinu prodlužovací šňůry s konektory jack 3,5 mm. Cena této šňůry je srovnatelná s cenou 2 konektorů a kusu stíněné dvojlinky. Ušetříte si tak nervy při pájení kabelu na konektor z termoplastické hmoty (který vůl to mohl vymyslet), což se zhusta nepovede. Kabel si však překontrolujte. Já jsem měl signál levého kanálu vedený červeným a pravého kanálu bílým vodičem. Protože jsem kabel připojil podle barev, měl jsem pak přehozeny signály levého a pravého kanálu. Zesilovač nemá žádné záludnosti a měl by pracovat na první zapojení.</p><p><img src="data:image/gif;base64," /></p><p>Obr. 2. Vhodný způsob propojení zemí v zesilovači<br />Fig. 2. Advisable ground connection</p><p><img src="data:image/jpeg;base64," /><br />Obr. 3. Zesilovač k PC v papírové (!) krabici. Celkový pohled - a), vntřek - b), deska zesilovače - c)<br />Fig. 3. PC amp in paper (!) box. Front wiev - a), inside wiev - b), amplifier board - c)</p><p><strong>Rozpiska součástek</strong></p><table><tr><td><p>R1, R2</p></td><td><p>10 kOhm</p></td><td rowspan="11"><p> </p></td><td><p>C1, C2</p></td><td><p>220 nF/63 V, fóliový</p></td></tr><tr><td><p>R3</p></td><td><p>1,5 kOhm</p></td><td><p>C3</p></td><td><p>100 µF, elektrolyt.</p></td></tr><tr><td><p>R4</p></td><td><p>470 Ohm</p></td><td><p>C4</p></td><td><p>100 nF/50 V, keramický</p></td></tr><tr><td><p>P</p></td><td><p>2x 5 kOhm, logaritmický potenciometr</p></td><td><p>C5, C6</p></td><td><p>1000 µF/10 V, elektrolyt.</p></td></tr><tr><td><p> </p></td><td><p> </p></td><td><p>C7, C8</p></td><td><p>2200 µF/16 V nebo 1x 4700 µF</p></td></tr><tr><td><p>LED</p></td><td><p>libovolná / arbitrary</p></td><td><p>C9</p></td><td><p>10 nF/250 VAC, fóliový</p></td></tr><tr><td><p>D1 až D4</p></td><td><p>1N4001 nebo 1x B250C1000</p></td><td><p> </p></td><td><p> </p></td></tr><tr><td><p>IO1</p></td><td><p>TDA1517</p></td><td><p>konektory</p></td><td><p>jack 3,5 mm 2x</p></td></tr><tr><td><p> </p></td><td><p> </p></td><td><p> </p></td><td><p>svorka pro přívody k reproduktorům<br />speakers clips</p></td></tr><tr><td><p>Tr</p></td><td><p>transformátor 230/9 V, 5 VA</p></td><td><p>přepínač</p></td><td><p>2 polohy, 2 kontakty</p></td></tr><tr><td><p> </p></td><td><p> </p></td><td><p>síťový spínač</p></td><td><p>2 polohy, 2 kontakty (KNX2)</p></td></tr></table>', '[]', '[]', NULL, '[]', NULL, '[]', '2026-09-16 12:46:09.255246+00');


