INSERT INTO "public"."recipes" ("slug", "title", "shortDescription", "image", "imageAlt", "date", "intro", "ingredients", "steps", "notes", "servings", "prepTime", "created_at", "description") VALUES
	('udene-klobasky', 'Uzené klobásky z udírny', 'Tradiční české klobásky uzené za studena s dřevěným uzeným aroma a zlatavou barvou.', '/recipes/udene-klobasky.jpg', 'Grilované klobásy a uzeniny na roštu', '2026-07-05', 'Když zrovna nepájím, sedím u udírny a hlídám klobásy. Tady je můj osvědčený recept na domácí uzené klobásky, které dělám každé léto.', '[{"name": "Vepřové maso (plec)", "amount": "1 kg"}, {"name": "Vepřové sádlo", "amount": "200 g"}, {"name": "Solný nálev (nitritovaná sůl)", "amount": "22 g"}, {"name": "Mletý černý pepř", "amount": "1 lžička"}, {"name": "Mletý nové koření", "amount": "1/2 lžičky"}, {"name": "Česnek granulovaný", "amount": "1 lžička"}, {"name": "Střeva (ovčí nebo vepřová)", "amount": "dle potřeby"}]', '[{"body": "Maso a sádlo nakrájej na kostky cca 2–3 cm. Smíchej se solí, pepřem, novým kořením a česnekem. Nech v chladu 24 hodin proležet."}, {"body": "Několik hodin před náplní namoč střeva do vlažné vody, aby změkla a dala se snadno navléct na stříkačku."}, {"body": "Naplň střeva masovou směsí pomocí klobásové stříkačky. Dělej klobásky dlouhé cca 15 cm, provážej nebo spiráluj."}, {"body": "Klobásky pověz do udírny a udři za studena při 50–60°C po dobu 4–6 hodin. Použij bukové nebo dřevěné hobliny."}, {"body": "Po uzení klobásky nech zchladnout a ulož do chladu. Nech odležet minimálně 24 hodin před konzumací."}]', 'Teplota v udírně nesmí překročit 60°C – jinak se klobásky upečou místo uzení. Dbej na to, aby dřevo nehořelo, jen tlelo.', 'cca 10 klobásek', '30 minut + odležení 24 h + uzení 4–6 h', '2026-09-10 20:05:45.383276+00', NULL),
	('rybar-pstruh-na-morech', 'Pstruh na másle s bylinkami', 'Jednoduchý recept na čerstvě uloveného pstruha – klasika pro rybáře od vody.', '/recipes/rybar-pstruh-na-morech.jpg', 'Muž rybařící u klidného jezera s prutem', '2026-06-20', 'Když mám štěstí u vody, připravím si čerstvého pstruha přímo na břehu. Recept je jednoduchý – čerstvá ryba, máslo, bylinky a trocha citronu.', '[{"name": "Pstruh (celý, vykuchaný)", "amount": "1 ks (cca 400 g)"}, {"name": "Máslo", "amount": "50 g"}, {"name": "Citron", "amount": "1/2 ks"}, {"name": "Čerstvý tymián", "amount": "snítka"}, {"name": "Čerstvý rozmarýn", "amount": "snítka"}, {"name": "Sůl a pepř", "amount": "dle chuti"}, {"name": "Olivový olej", "amount": "1 lžíce"}]', '[{"body": "Pstruha očisti, osuš papírovým ubrouskem. Zvenku i zevnitř osol a opepři. Do břicha vlož snítky tymiánu a rozmarýnu."}, {"body": "Rozpal pánev nebo gril s trochou olivového oleje. Polož pstruha na pánev a opeč z jedné strany 4–5 minut, dokud kůže nezezlátne."}, {"body": "Otoč a opeč z druhé strany další 3–4 minuty. Během opékání přidej máslo a lžící polévej rybu máslem."}, {"body": "Na konci vymačkaj na rybu šťávu z půlky citronu. Podávej s čerstvým chlebem a plátkem citronu."}]', 'Pozor, aby ses nepřepekl – pstruh je rychle hotový. Maso má být u kosti jemně růžové, ne bílé suché.', '1 porce', '15 minut', '2026-09-10 20:05:45.383276+00', NULL),
	('cesnekova-sul', 'Domácí česneková sůl', 'Legendární česneková sůl z Ostravy – dokonalé koření na maso, brambory i pečivo.', '/recipes/cesnekova-sul.jpg', 'Stroužek česneku na vrstvě soli', '2026-08-01', 'Moje domácí česneková sůl je prý legendární – alespoň to říkají rodina a přátelé. Recept je jednoduchý, ale výsledek je neuvěřitelný. Hodí se na grilované maso, brambory, pečivo i do polévek.', '[{"name": "Hrubá mořská sůl", "amount": "200 g"}, {"name": "Česnek (čerstvý)", "amount": "5–6 stroužků"}, {"name": "Sušený tymián", "amount": "1 lžička"}, {"name": "Sušený rozmarýn", "amount": "1/2 lžičky"}, {"name": "Černý pepř mletý", "amount": "1/2 lžičky"}]', '[{"body": "Oloupej stroužky česneku a rozmělj je v hmoždíři na pastu. Můžeš použít i lis, ale v hmoždíři se uvolní více chuti."}, {"body": "Přidej hrubou mořskou sůl k česnekové pastě a důkladně promíchej. Sůl začne absorbovat vlhkost z česneku."}, {"body": "Přidej sušený tymián, rozmarýn a černý pepř. Všechno důkladně promíchej."}, {"body": "Rozlož směs na pečící papír a nech sušit při pokojové teplotě 24–48 hodin. Můžeš ji i sušit v troubě při 50°C s mírně pootevřenými dvířky po dobu 2–3 hodin."}, {"body": "Po usušení přesuň do skleněné nádoby s těsným víčkem. Skladuj na chladném a suchém místě. Výdržnost je 3–6 měsíců."}]', 'Pro extra pikantní verzi přidej špetku chilli vloček. Pro jemnější chuť použij jemnější sůl.', '200 g', '10 minut + sušení 24 h', '2026-09-10 20:05:45.383276+00', NULL),
	('dobra-frankfurtska-polevka', 'Dobrá frankfurtská polévka', 'Cibuli oloupeme a nakrájíme nadrobno. Párky nakrájíme na kolečka. Brambory oloupeme a nakrájíme na malé kostičky.', 'https://crulaktbptkfhzqywddg.supabase.co/storage/v1/object/public/images/recipes/1789557796598_frankfurtska-jemna-polevka.png', 'Dobrá frankfurtská polévka', '2026-09-16', '', '[{"name": "sádla", "amount": "20 g"}, {"name": "cibule", "amount": "1 střední"}, {"name": "vídeňských párků", "amount": "4 nožičky (150 g)"}, {"name": "žíce hladké mouky", "amount": "1 l"}, {"name": "žíce mleté sladké papriky", "amount": "2 l"}, {"name": "stroužky česneku", "amount": "2 větší"}, {"name": "itr hovězího vývaru", "amount": "1 l"}, {"name": "brambory (cca 300 g)", "amount": "3 střední"}, {"name": "sůl", "amount": ""}, {"name": "mletý pepř", "amount": ""}, {"name": "žíce sušené majoránky", "amount": "1 l"}, {"name": "čerstvá bazalka", "amount": ""}, {"name": "čerstvá pažitka", "amount": ""}]', '[{"body": "Cibuli oloupeme a nakrájíme nadrobno. Párky nakrájíme na kolečka. Brambory oloupeme a nakrájíme na malé kostičky."}, {"body": "V hrnci rozpálíme sádlo, snížíme trochu plamen a restujeme na něm cibulku dozlatova."}, {"body": "Poté přidáme nakrájené párky a za stálého míchání rovnoměrně opečeme. Zaprášíme lžící mouky a minutu restujeme. Pak přidáme papriku a opět opékáme asi minutu."}, {"body": "Česnek oloupeme a prolisujeme do hrnce, promícháme a necháme rozvonět. Poté do hrnce přilijeme všechen vývar a směs rozmícháme dohladka (v polévce by neměly být hrudky)."}, {"body": "Osolíme, opepříme a přivedeme k varu. Přidáme brambory, zakryjeme poklicí a vaříme 15–20 minut."}, {"body": "Na konci přidáme majoránku, bazalku, pažitku a necháme asi minutu prohřát. Poté můžeme servírovat."}]', '', '', '', '2026-09-16 12:25:23.359401+00', '');


